/*
 * headless_clock_verbs.c - Clock processor verb implementations
 *
 * Originally generated by tools/kernelverbs_parser/generate_processor_stubs.py,
 * now contains hand-written implementations for most clock verbs.
 *
 * DO NOT regenerate - this file contains production implementations.
 *
 * Implementation status:
 * - clock.now, clock.ticks, clock.milliseconds: IMPLEMENTED (2025-12-15 by Codex)
 * - clock.sleepfor, clock.waitseconds: IMPLEMENTED
 * - Uses portable time layer (frontier_time_*) for cross-platform compatibility
 * - clock.resetclock: STUB (not yet implemented)
 */

#include "frontier.h"
#include "standard.h"

#include "memory.h"
#include "strings.h"
#include "lang.h"
#include "langinternal.h"
#include "tablestructure.h"
#include "timedate.h"
#include "time_portable.h"
#include "logging.h"

/* Maximum sleep duration: 24 hours in seconds. Fix: #112 */
#define MAX_SLEEP_SECONDS 86400L
/* Maximum sleep duration in sixtieths: 24 hours * 60 seconds * 60 ticks */
#define MAX_SLEEP_SIXTIETHS (MAX_SLEEP_SECONDS * 60L)

/* Token enum for all verbs in the clock processor */
enum {
    clov_now = 0,
    clov_set = 1,
    clov_sleepfor = 2,
    clov_ticks = 3,
    clov_milliseconds = 4,
    clov_waitseconds = 5,
    clov_waitsixtieths = 6
};

static boolean clock_valueproc(short token, hdltreenode hparam1,
                                     tyvaluerecord *vreturned,
                                     bigstring bserror) {
    (void)bserror;  /* Suppress unused parameter warning for implemented verbs */

    switch(token) {
        case clov_now:
            /* Verb: clock.now - implemented using portable timenow() */
            if (!langcheckparamcount(hparam1, 0))
                return false;
            return setdatevalue(timenow(), vreturned);

        case clov_set:
            /* clock.set - returns appropriate error (not a stub)
             * @IMPLEMENTED - Correctly implemented to return security error */
            if (bserror)
                copystring(PSTRING("\102", "Can't set system time because it requires administrator privileges"), bserror);
            return false;

        case clov_sleepfor: {
            /* Verb: clock.sleepfor - headless implementation using portable sleep */
            long ctseconds;

            flnextparamislast = true;

            if (!getlongvalue(hparam1, 1, &ctseconds))
                return false;

            /* Validate non-negative duration */
            if (ctseconds < 0) {
                if (bserror) copystring(PSTRING("\060", "Can't sleep because negative duration is invalid"), bserror);
                return false;
            }

            /* Clamp to 24-hour maximum (#112) */
            if (ctseconds > MAX_SLEEP_SECONDS) {
                log_warn(LOG_COMP_GENERAL, "clock.sleepfor: duration %ld seconds exceeds 24-hour max, clamping to %ld", ctseconds, MAX_SLEEP_SECONDS);
                ctseconds = MAX_SLEEP_SECONDS;
            }

            /* Sleep for the specified number of seconds */
            if (ctseconds > 0)
                frontier_time_sleep_millis((uint32_t)(ctseconds * 1000));

            (*vreturned).data.flvalue = true;
            return true;
        }

        case clov_ticks:
            /* Verb: clock.ticks - implemented using portable gettickcount() */
            if (!langcheckparamcount(hparam1, 0))
                return false;
            return setlongvalue(gettickcount(), vreturned);

        case clov_milliseconds:
            /* Verb: clock.milliseconds - implemented using portable getmilliseconds() */
            if (!langcheckparamcount(hparam1, 0))
                return false;
            return setlongvalue(getmilliseconds(), vreturned);

        case clov_waitseconds: {
            /* Verb: clock.waitseconds - headless implementation using portable sleep */
            long ctseconds;

            flnextparamislast = true;

            if (!getlongvalue(hparam1, 1, &ctseconds))
                return false;

            /* Validate non-negative duration */
            if (ctseconds < 0) {
                if (bserror) copystring(PSTRING("\057", "Can't wait because negative duration is invalid"), bserror);
                return false;
            }

            /* Clamp to 24-hour maximum (#112) */
            if (ctseconds > MAX_SLEEP_SECONDS) {
                log_warn(LOG_COMP_GENERAL, "clock.waitseconds: duration %ld seconds exceeds 24-hour max, clamping to %ld", ctseconds, MAX_SLEEP_SECONDS);
                ctseconds = MAX_SLEEP_SECONDS;
            }

            /* Sleep for the specified number of seconds */
            if (ctseconds > 0)
                frontier_time_sleep_millis((uint32_t)(ctseconds * 1000));

            (*vreturned).data.flvalue = true;
            return true;
        }

        case clov_waitsixtieths: {
            /* Verb: clock.waitsixtieths - headless implementation using portable sleep */
            /* Sixtieths = 1/60th second, convert to milliseconds: ticks * 1000 / 60 ≈ ticks * 50 / 3 */
            long ctsixtieths;

            flnextparamislast = true;

            if (!getlongvalue(hparam1, 1, &ctsixtieths))
                return false;

            /* Convert 60ths of a second to milliseconds */
            if (ctsixtieths < 0) {
                if (bserror) copystring(PSTRING("\057", "Can't wait because negative duration is invalid"), bserror);
                return false;
            }

            /* Clamp to 24-hour maximum (#112) */
            if (ctsixtieths > MAX_SLEEP_SIXTIETHS) {
                log_warn(LOG_COMP_GENERAL, "clock.waitsixtieths: duration %ld sixtieths exceeds 24-hour max, clamping to %ld", ctsixtieths, MAX_SLEEP_SIXTIETHS);
                ctsixtieths = MAX_SLEEP_SIXTIETHS;
            }

            if (ctsixtieths > 0) {
                /* Prevent overflow by casting to int64_t before multiplication */
                uint32_t millis = (uint32_t)(((int64_t)ctsixtieths * 1000) / 60);
                frontier_time_sleep_millis(millis);
            }

            (*vreturned).data.flvalue = true;
            return true;
        }

        default:
            return false;
    }
}

boolean clockinitverbs(void) {
    hdlhashtable htable = nil;
    bigstring bsname;

    copystring(PSTRING("\005", "clock"), bsname);

    if (!newfunctionprocessor(bsname, &clock_valueproc, false, &htable))
        return false;

    pushhashtable(htable);

    #define ADD_VERB(name, tok) do { \
        bigstring bs; \
        copystring(name, bs); \
        if (!langaddkeyword(bs, tok)) { \
            pophashtable(); \
            return false; \
        } \
    } while(0)

    ADD_VERB(PSTRING("\003", "now"), clov_now);
    ADD_VERB(PSTRING("\003", "set"), clov_set);
    ADD_VERB(PSTRING("\010", "sleepfor"), clov_sleepfor);
    ADD_VERB(PSTRING("\005", "ticks"), clov_ticks);
    ADD_VERB(PSTRING("\014", "milliseconds"), clov_milliseconds);
    ADD_VERB(PSTRING("\013", "waitseconds"), clov_waitseconds);
    ADD_VERB(PSTRING("\015", "waitsixtieths"), clov_waitsixtieths);

    #undef ADD_VERB

    pophashtable();
    return true;
}
